def process(precipChatham, precipAmherst, precipBoston, precipAshburnham):
    import pandas as pd

    def _summer_total(df, city):
        d = df.copy()
        d = d[d['Year'].astype(str) == '2015']
        if d.empty:
            return pd.DataFrame([{'city': city, 'summer_rainfall': pd.NA}])

        def to_num(x):
            # values can be 'M' (missing) or strings; coerce to float
            return pd.to_numeric(pd.Series(x), errors='coerce').iloc[0]

        jun = to_num(d['Jun'].iloc[0])
        jul = to_num(d['Jul'].iloc[0])
        aug = to_num(d['Aug'].iloc[0])
        total = sum([v for v in [jun, jul, aug] if pd.notna(v)])
        # if all missing, set NA
        if pd.isna(jun) and pd.isna(jul) and pd.isna(aug):
            total = pd.NA
        return pd.DataFrame([{'city': city, 'summer_rainfall': total}])

    out = pd.concat([
        _summer_total(precipChatham, 'Chatham'),
        _summer_total(precipAmherst, 'Amherst'),
        _summer_total(precipBoston, 'Boston'),
        _summer_total(precipAshburnham, 'Ashburnham'),
    ], ignore_index=True)

    out = out.dropna(subset=['summer_rainfall']).sort_values('summer_rainfall', ascending=True, kind='mergesort').reset_index(drop=True)
    return out.head(1)
